      } as unknown as CreepLike;

      controller.execute(creep);

      // Should have searched for all structures (for filtering)
      expect(room.find).toHaveBeenCalledWith(
        FIND_STRUCTURES,
        expect.objectContaining({
          filter: expect.any(Function)
